        "actionDate": "2026-09-28",
        "status": "proposal_only",
        "summary": {
          "en": "Florida filed a motion for a temporary injunction seeking to bar development of new AI models without third-party-approved safeguards and to bar minors from using ChatGPT.",
          "zhHans": "佛罗里达提交临时禁令动议，要求在没有第三方批准安全防护的情况下禁止开发新 AI 模型，并禁止未成年人使用 ChatGPT。"
        },
        "newSourceIds": [
          "followup-20260929-florida-motion",
          "followup-20260929-florida-axios",
          "followup-20260929-florida-politico"
        ],
        "requiredReview": "Independent review and human approval are required before modifying the published event."
      },
      "sources": [
        {
          "sourceId": "followup-20260929-florida-motion",
          "url": "https://www.myfloridalegal.com/sites/default/files/plaintiffs_motion_for_temporary_injunction.pdf",
          "originId": "florida-openai-injunction-motion"
        },
        {
          "sourceId": "followup-20260929-florida-axios",
          "url": "https://www.axios.com/2026/09/28/florida-openai-chatgpt-injunction-uthmeier",
          "originId": "axios-florida-injunction-reporting"
        },
        {
          "sourceId": "followup-20260929-florida-politico",
          "url": "https://www.politico.com/news/2026/09/28/florida-injunction-openai-development-01095061",
          "originId": "politico-florida-injunction-reporting"
        }
      ]
    },
    {
      "eventId": "meta-muse-personal-agent-2026",
      "proposal": {
        "baseEventId": "meta-muse-personal-agent-2026",
        "decision": "update",
        "actionDate": "2026-09-21",
        "status": "proposal_only",
        "summary": {
          "en": "Patrick Wardle disclosed a macOS Muse flaw that allowed a local process to redirect an undocumented dictation endpoint and leverage permissions already granted to Muse; Meta subsequently removed the debug preference in a hotfix.",
          "zhHans": "Patrick Wardle 披露 macOS 版 Muse 的一项漏洞，本地进程可重定向未公开的听写端点并利用用户已授予 Muse 的权限；Meta 随后在热修复中移除了该调试偏好设置。"
        },
        "newSourceIds": [
          "followup-20260929-meta-muse-poc",
          "followup-20260929-meta-muse-hackernews",
          "followup-20260929-meta-muse-infoq"
        ],
        "requiredReview": "Independent review and human approval are required before modifying the published event."
      },
      "sources": [
        {
          "sourceId": "followup-20260929-meta-muse-poc",
