          "originId": "wardle-not-a-mused-poc"
        },
        {
          "sourceId": "followup-20260929-meta-muse-hackernews",
          "url": "https://thehackernews.com/2026/09/one-hidden-meta-muse-setting-could-let.html",
          "originId": "wardle-not-a-mused-poc"
        },
        {
          "sourceId": "followup-20260929-meta-muse-infoq",
          "url": "https://www.infoq.com/news/2026/09/meta-muse-zeroday/",
          "originId": "infoq-meta-muse-reporting"
        }
      ]
    }
  ],
  "prompt": "UPDATE_REVIEW_PROMPT.md",
  "canonicalWrites": false
}

